install-managed.ps1:
﻿<#
Excellence gép-padló telepítő natív Windowsra (#755). Rendszergazdai PowerShellből, idempotensen.

  .\install-managed.ps1 floor.json
  .\install-managed.ps1 floor.json -User CEG\kovacs.anna -Python "C:\Program Files\Python312\python.exe"
  pwsh ./install-managed.ps1 floor.json -Prefix /tmp/stage     # teszthez, admin nélkül

A floor.json a GET /api/client-policy/machine-floor?userId=...&platform=windows válasza.
WSL-ben futó Hermeshez a disztribúción belül az install-managed.sh kell, nem ez.

Felteszi (C:\ProgramData\Excellence, csak SYSTEM és Administrators írhatja):
  hermes\{config.yaml,.env,excellence-install-id}   a letöltött padló
  bin\exc-token(.cmd), bin\exc-guard(.cmd)          token-segéd és shell-hook tartalék
  hermes-plugins\excellence-guard                   a Guard plugin
és gépszintű HERMES_MANAGED_DIR-t állít, mert a Hermes Windowson nem keres natív managed helyet.
#>
param(
  [Parameter(Mandatory = $true, Position = 0)][string]$Package,
  [string]$Python = '',
  [string]$User = '',
  [string]$Prefix = ''
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2

function Fail([string]$message) {
  [Console]::Error.WriteLine($message)
  exit 1
}

$Testing = $Prefix -ne ''
if ($Testing) {
  $Root = Join-Path $Prefix 'ProgramData/Excellence'
} else {
  $Root = 'C:\ProgramData\Excellence'
  $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
  if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Fail 'A telepítő rendszergazdaként fut: nyiss egy "Futtatás rendszergazdaként" PowerShellt.'
  }
}
$Managed = Join-Path $Root 'hermes'
$Bin = Join-Path $Root 'bin'
$PluginRoot = Join-Path $Root 'hermes-plugins'
$Names = 'config.yaml', '.env', 'excellence-install-id'

# A Guard és a token-segéd a padló élesítése előtt legyen jelen.
foreach ($asset in 'exc_token.py', 'exc-guard', 'excellence-guard/plugin.yaml', 'excellence-guard/excellence_paths.py') {
  if (-not (Test-Path -LiteralPath (Join-Path $PSScriptRoot $asset) -PathType Leaf)) { Fail "Hiányzó telepítőfájl: $asset" }
}

# --- Python: a .cmd wrapper ezt indítja -I kapcsolóval -------------------------------------
if (-not $Python) {
  foreach ($candidate in 'py -3', 'python3', 'python') {
    $parts = $candidate -split ' '
    if (-not (Get-Command $parts[0] -ErrorAction SilentlyContinue)) { continue }
    $found = & $parts[0] @($parts | Select-Object -Skip 1) -c 'import sys; print(sys.executable)' 2>$null
    if ($LASTEXITCODE -eq 0 -and $found) { $Python = "$found".Trim(); break }
  }
}
if (-not $Python -or -not (Test-Path -LiteralPath $Python -PathType Leaf)) {
  Fail 'Nem találok Pythont. Telepíts gépszintű Python 3-at (minden felhasználónak), vagy add meg: -Python <python.exe útvonala>.'
}
& $Python -I -c 'import sys; sys.exit(sys.version_info < (3, 8))'
if ($LASTEXITCODE -ne 0) { Fail "Legalább Python 3.8 kell: $Python" }
if (-not $Testing) {
  # A munkatárs által írható Python kicserélhető lenne, és vele a Guard döntése is.
  $profiles = [Environment]::ExpandEnvironmentVariables((Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList').ProfilesDirectory)
  if ($Python.StartsWith($profiles.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) {
    Fail "A Python a felhasználói mappában van ($Python). Telepíts gépszintű Pythont (pl. C:\Program Files), és add meg -Python kapcsolóval."
  }
  if ($Python -match '[^\x20-\x7E]') { Fail "A Python útvonala csak ASCII karaktert tartalmazhat: $Python" }
}

# --- Csomag ellenőrzése: hibás bemenet nem módosítja a régi padlót -----------------------
$Utf8 = New-Object Text.UTF8Encoding($false)
$Sha = [Security.Cryptography.SHA256]::Create()
function Hex([byte[]]$bytes) { -join ($Sha.ComputeHash($bytes) | ForEach-Object { $_.ToString('x2') }) }

try {
  $pkg = [IO.File]::ReadAllText((Resolve-Path -LiteralPath $Package), $Utf8) | ConvertFrom-Json
  if ($pkg.platform -ne 'windows') { throw 'Ez nem Windows-csomag: töltsd le újra a platform=windows paraméterrel.' }
  if (-not ($pkg.installId -is [string]) -or -not $pkg.installId -or $pkg.files.'excellence-install-id' -ne "$($pkg.installId)`n") { throw 'Hibás installId' }
  $body = "excellence-managed-dir-v1`n"
  foreach ($name in $Names) {
    $text = $pkg.files.$name
    if (-not ($text -is [string]) -or -not $text.EndsWith("`n")) { throw "Hiányzó vagy hibás managed fájl: $name" }
    $body += "$name`n$(Hex $Utf8.GetBytes($text))`n"
  }
  if ($pkg.managedDirHash -ne (Hex $Utf8.GetBytes($body))) { throw 'A csomag hash-e nem egyezik a tartalommal' }
} catch {
  Fail "Hibás csomag, nem telepítem: $($_.Exception.Message)"
}

# Előre elhelyezett junction/symlink nem vezetheti máshová a rendszergazdai írást.
function Assert-NoReparse([string]$base, [string]$target) {
  $path = $target
  while ($path -and $path.Length -ge $base.Length) {
    $item = Get-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue
    if ($item -and ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) { Fail "A telepítési útvonal nem lehet symlink vagy junction: $path" }
    $path = Split-Path -Parent $path
  }
  if (Test-Path -LiteralPath $target) {
    $bad = Get-ChildItem -LiteralPath $target -Recurse -Force | Where-Object { $_.Attributes -band [IO.FileAttributes]::ReparsePoint } | Select-Object -First 1
    if ($bad) { Fail "A telepítési könyvtár nem tartalmazhat symlinket vagy junctiont: $($bad.FullName)" }
  }
}

# --- Gépi könyvtár: csak SYSTEM és Administrators írhatja ---------------------------------
New-Item -ItemType Directory -Force -Path $Root | Out-Null
Assert-NoReparse $Root $Root
if (-not $Testing) {
  # SID-ek, mert a csoportnevek a Windows nyelvétől függnek. A /reset leveszi a korábban
  # (akár a munkatárs által) beállított explicit jogokat, a gyökér jogát a gyerekek öröklik.
  & icacls $Root /setowner '*S-1-5-32-544' /T /C /Q | Out-Null
  & icacls $Root /reset /T /C /Q | Out-Null
  & icacls $Root /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-32-545:(OI)(CI)RX' /Q | Out-Null
  if ($LASTEXITCODE -ne 0) { Fail "Nem sikerült a jogosultságot beállítani: $Root" }
}
New-Item -ItemType Directory -Force -Path $Managed, $Bin, $PluginRoot | Out-Null

$stage = Join-Path $Managed ('.stage-' + [guid]::NewGuid())
New-Item -ItemType Directory -Path $stage | Out-Null
try {
  foreach ($name in $Names) { [IO.File]::WriteAllBytes((Join-Path $stage $name), $Utf8.GetBytes($pkg.files.$name)) }
  foreach ($name in $Names) { Move-Item -LiteralPath (Join-Path $stage $name) -Destination (Join-Path $Managed $name) -Force }
} finally {
  Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
}
Write-Output $pkg.installId
Write-Output $pkg.managedDirHash

Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'exc_token.py') -Destination (Join-Path $Bin 'exc-token') -Force
Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'exc-guard') -Destination (Join-Path $Bin 'exc-guard') -Force
Copy-Item -LiteralPath (Join-Path $PSScriptRoot 'excellence-guard\excellence_paths.py') -Destination (Join-Path $Bin 'excellence_paths.py') -Force
foreach ($tool in 'exc-token', 'exc-guard') {
  # A config.yaml ezeket hívja; a Windows nem ismeri a shebanget. A Hermes UTF-8-ként olvas.
  [IO.File]::WriteAllText((Join-Path $Bin "$tool.cmd"), "@`"$Python`" -I -X utf8 `"%~dp0$tool`" %*`r`n", [Text.Encoding]::ASCII)
}

function Copy-Plugin([string]$base, [string]$dest) {
  Assert-NoReparse $base $dest
  New-Item -ItemType Directory -Force -Path $dest | Out-Null
  Copy-Item -Path (Join-Path (Join-Path $PSScriptRoot 'excellence-guard') '*') -Destination $dest -Recurse -Force
}
Copy-Plugin $PluginRoot (Join-Path $PluginRoot 'excellence-guard')

# --- A munkatárs Hermes-profiljai: %LOCALAPPDATA%\hermes, profilonként saját plugin-mappa --
$HermesHome = ''
$Sid = ''
$profileDir = ''
if ($Testing) {
  $HermesHome = Join-Path $Prefix 'home/AppData/Local/hermes'
} else {
  if (-not $User) { $User = (Get-CimInstance Win32_ComputerSystem).UserName }
  if ($User) {
    $Sid = (New-Object Security.Principal.NTAccount($User)).Translate([Security.Principal.SecurityIdentifier]).Value
    $profileDir = (Get-CimInstance Win32_UserProfile -Filter "SID='$Sid'").LocalPath
    if ($profileDir) { $HermesHome = Join-Path $profileDir 'AppData\Local\hermes' }
  }
}
if ($HermesHome) {
  $profilesDir = Join-Path $HermesHome 'profiles'
  $bots = @()
  if ($pkg.PSObject.Properties['bots'] -and $pkg.bots) { $bots = @($pkg.bots) }
  $safe = '^exc-[a-z0-9][a-z0-9-]{0,54}$'
  $botFiles = @('SOUL.md', 'profile.yaml', 'config.yaml', 'distribution.yaml')
  foreach ($bot in $bots) {
    $profileName = [string]$bot.profile
    if ($profileName -notmatch $safe -or $profileName.Length -gt 60) { continue }
    $dest = Join-Path $profilesDir $profileName
    Assert-NoReparse $HermesHome $dest
    New-Item -ItemType Directory -Force -Path $dest | Out-Null
    foreach ($name in $botFiles) {
      $text = $bot.files.$name
      if ($text -is [string]) {
        [IO.File]::WriteAllText((Join-Path $dest $name), $text, $Utf8)
      }
    }
    foreach ($leftover in @('.enterprise-agent', (Join-Path 'skills' 'excellence'))) {
      $path = Join-Path $dest $leftover
      if (Test-Path -LiteralPath $path) { Remove-Item -LiteralPath $path -Recurse -Force }
    }
  }
  # A Bot az azonos MCP-URL-ű default belépőt kapja; név szerint a default `excellence` más tenanté lehet.
  & $Python -I -X utf8 (Join-Path $Bin 'exc-token') --share $HermesHome
  if ($LASTEXITCODE -ne 0) { Fail 'A Bot-belépők szinkronja nem sikerült.' }
  Copy-Plugin $HermesHome (Join-Path $HermesHome 'plugins/excellence-guard')
  if (Test-Path -LiteralPath $profilesDir -PathType Container) {
    foreach ($botProfile in Get-ChildItem -LiteralPath $profilesDir -Directory -Force) {
      Copy-Plugin $HermesHome (Join-Path $botProfile.FullName 'plugins/excellence-guard')
    }
  }
} else {
  Write-Output 'Nem találtam bejelentkezett munkatársat: a Guard pluginját a -User kapcsolóval másold a profiljába.'
}

# --- A Hermes ebből tudja, hol a managed könyvtár -------------------------------------------
function Clear-ManagedDirValue([string]$Key) {
  if ((Test-Path $Key) -and (Get-ItemProperty $Key).PSObject.Properties['HERMES_MANAGED_DIR']) {
    Remove-ItemProperty -Path $Key -Name 'HERMES_MANAGED_DIR'
    Write-Output 'A munkatárs saját HERMES_MANAGED_DIR beállítását eltávolítottam.'
  }
}

function Remove-UnloadedUserManagedDir([string]$ProfileDir) {
  # A ki nem töltött profil a következő bejelentkezéskor visszahozná a felülírást.
  if (-not $ProfileDir) { return }
  $dat = Join-Path $ProfileDir 'NTUSER.DAT'
  if (-not (Test-Path -LiteralPath $dat)) { return }
  $hive = 'HKU\ExcellenceFloor'
  & reg load $hive $dat 2>$null
  if ($LASTEXITCODE -ne 0) { return }
  $unloaded = $false
  try {
    Clear-ManagedDirValue 'Registry::HKEY_USERS\ExcellenceFloor\Environment'
  } finally {
    for ($i = 0; $i -lt 5 -and -not $unloaded; $i++) {
      [gc]::Collect()
      [gc]::WaitForPendingFinalizers()
      & reg unload $hive 2>$null
      if ($LASTEXITCODE -eq 0) { $unloaded = $true } else { Start-Sleep -Milliseconds 200 }
    }
  }
  if (-not $unloaded) {
    Write-Output 'A profilt nem tudtam visszazárni. Ha a munkatárs bejelentkezése hibázik, indítsd újra a gépet.'
  }
}

function Publish-EnvironmentChange {
  if (-not ('Excellence.EnvBroadcast' -as [type])) {
    Add-Type -Namespace Excellence -Name EnvBroadcast -MemberDefinition @'
[System.Runtime.InteropServices.DllImport("user32.dll", CharSet = System.Runtime.InteropServices.CharSet.Unicode)]
public static extern System.IntPtr SendMessageTimeout(System.IntPtr hWnd, int Msg, System.IntPtr wParam, string lParam, int fuFlags, int uTimeout, out System.IntPtr lpdwResult);
'@
  }
  $broadcast = [IntPtr]::new(0xffff)
  $result = [IntPtr]::Zero
  [void][Excellence.EnvBroadcast]::SendMessageTimeout($broadcast, 0x001A, [IntPtr]::Zero, 'Environment', 2, 5000, [ref]$result)
}

if (-not $Testing) {
  [Environment]::SetEnvironmentVariable('HERMES_MANAGED_DIR', $Managed, 'Machine')
  # A felhasználói változó felülírja a gépszintűt. Minden betöltött profilból kivesszük.
  $loaded = @{}
  Get-ChildItem Registry::HKEY_USERS | ForEach-Object {
    $name = $_.PSChildName
    if ($name -match '^S-1-5-21-' -and $name -notlike '*_Classes') {
      $loaded[$name] = $true
      Clear-ManagedDirValue "Registry::HKEY_USERS\$name\Environment"
    }
  }
  if ($Sid -and -not $loaded.ContainsKey($Sid)) { Remove-UnloadedUserManagedDir $profileDir }
  Publish-EnvironmentChange
}

Write-Output "Gép-padló: $Managed"
Write-Output "Binárisok: $Bin"
$hermes = Get-Command hermes -ErrorAction SilentlyContinue
if ($hermes) {
  Write-Output '--- hermes config ---'
  $env:HERMES_MANAGED_DIR = $Managed
  try { & $hermes.Source config } catch { Write-Output 'A hermes config most nem futott le. A telepítés ettől még megvan.' }
} else {
  Write-Output 'A hermes nincs a PATH-on. A telepítés megvan; a Hermes következő indításakor olvassa a céges beállítást.'
}
if (-not $Testing) { Write-Output 'Kész. Zárd be a Hermest, ha meg van nyitva, és nyisd meg újra. Kijelentkezni nem kell.' }

exc_token.py:
#!/usr/bin/python3 -I
"""exc-token — a Hermes `providers.excellence.key_cmd` helper (#746 V1-2, D1).

A kiszolgált Bot-profil MCP OAuth tokenjét 10 perces Model Gateway JWT-re cseréli, és
`exp - 60 s`-ig cache-eli a profil könyvtárában (a key_cmd kérésenként fut, K11).
Stdout = JSON (access_token + expires_in); hibánál nem nulla exit kód + hétköznapi nyelvű stderr. Csak stdlib.
"""
import calendar
import importlib.util
import json
import os
import re
import sys
import time
import urllib.error
import urllib.request
import uuid
from urllib.parse import urlparse

LEEWAY = 60
SERVER = os.environ.get("EXCELLENCE_MCP_SERVER", "excellence")
CACHE_NAME = "excellence-gateway-token.json"


def _load_paths():
    # A `-I` nem teszi a szkript mappáját a sys.path-ra, ezért fájlból töltjük.
    here = os.path.dirname(os.path.abspath(__file__))
    for folder in (here, os.path.join(here, "excellence-guard")):
        path = os.path.join(folder, "excellence_paths.py")
        if os.path.isfile(path):
            spec = importlib.util.spec_from_file_location("excellence_paths_token", path)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            return mod
    raise ImportError("excellence_paths")


_paths = _load_paths()
MANAGED_DIR = _paths.default_managed_dir()


def default_home():
    return _paths.default_home()


class Fail(Exception):
    pass


def server_block(config_text, name):
    """A `mcp_servers.<name>` blokk sorai (behúzás alapján; yaml-lib nélkül)."""
    lines, out, base, in_servers = config_text.splitlines(), [], None, False
    for ln in lines:
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        indent = len(ln) - len(ln.lstrip())
        if indent == 0:
            in_servers = ln.strip() == "mcp_servers:"
            base = None
        elif in_servers and base is None and ln.strip() == f"{name}:":
            base = indent
        elif base is not None:
            if indent <= base:
                break
            out.append(ln.strip())
    return out


def read_profile(home):
    try:
        cfg = open(os.path.join(home, "config.yaml"), encoding="utf-8").read()
        block = server_block(cfg, SERVER)
        url = _server_url(cfg, SERVER)
        if not url:
            raise OSError
    except OSError:
        raise Fail("Ennek a Hermes-profilnak nincs beállított Excellence-kapcsolata. Kapcsold össze újra a Hermes Excellence-kapcsolatát.")
    # Az alap profilhoz nincs asszisztens kötve (#858): agent nélkül a szerver választ egyet az elérhetők közül.
    agent = next((m.group(1) for ln in block if (m := re.match(r"['\"]?X-Excellence-Agent-Id['\"]?:\s*['\"]?([\w-]+)", ln, re.I))), None)
    u = urlparse(url)
    return f"{u.scheme}://{u.netloc}", u.path.rstrip("/").rsplit("/", 1)[-1], agent


def install_id(home):
    env = os.environ.get("EXC_INSTALL_ID", "").strip()
    if env:
        return env
    for path in (os.path.join(MANAGED_DIR, "excellence-install-id"), os.path.join(home, "excellence-install-id")):
        try:
            v = open(path).read().strip()
            if v:
                return v
        except OSError:
            pass
    v = str(uuid.uuid4())  # v1: csak heartbeat-korreláció, nem eszközkötés
    try:
        open(os.path.join(home, "excellence-install-id"), "w").write(v)
    except OSError:
        pass
    return v


def parent_hermes_home(home):
    """A vékony Bot (`.../profiles/exc-…`) default Hermes-profilja. Más HERMES_HOME-ra None."""
    home = os.path.abspath(home)
    parent, name = os.path.split(home.rstrip(os.sep))
    grand, profiles = os.path.split(parent)
    if profiles == "profiles" and name.startswith("exc-"):
        return grand
    return None


def _server_url(config_text, name):
    return next((m.group(1) for ln in server_block(config_text, name) if (m := re.match(r"url:\s*['\"]?(\S+?)['\"]?$", ln))), None)


def _server_names(config_text):
    names, child, in_servers = [], None, False
    for ln in config_text.splitlines():
        if not ln.strip() or ln.lstrip().startswith("#"):
            continue
        indent = len(ln) - len(ln.lstrip())
        if indent == 0:
            in_servers, child = ln.strip() == "mcp_servers:", None
        elif in_servers and (child is None or indent == child) and ln.strip().endswith(":"):
            child = indent
            names.append(ln.strip()[:-1].strip("'\""))
    return names


def parent_server_name(home, parent):
    """A default profil azon MCP-szervere, amely a Bot szerverével azonos URL-re mutat.

    A default profilban az `excellence` név más bérlőt is jelenthet (pl. saját tenant), a Bot
    tenantjára tett belépés pedig `excellence-<tenant>` néven áll. Más URL belépőjét nem vesszük át.
    """
    try:
        url = _server_url(open(os.path.join(home, "config.yaml"), encoding="utf-8").read(), SERVER)
    except OSError:
        url = None
    try:
        cfg = open(os.path.join(parent, "config.yaml"), encoding="utf-8").read()
    except OSError:
        return SERVER
    names = _server_names(cfg)
    matches = [n for n in names if url and _server_url(cfg, n) == url]
    if SERVER in matches:
        return SERVER
    if matches:
        return matches[0]
    return None if SERVER in names else SERVER


def _copy_login(src_dir, src_name, dest_dir, dest_name):
    """Token + client + meta együtt; symlinket nem követünk és nem írunk."""
    copied = False
    if os.path.islink(src_dir) or os.path.islink(dest_dir):
        return False
    for suffix in (".json", ".client.json", ".meta.json"):
        src, dest = os.path.join(src_dir, src_name + suffix), os.path.join(dest_dir, dest_name + suffix)
        if os.path.islink(src) or not os.path.isfile(src) or os.path.islink(dest):
            continue
        os.makedirs(dest_dir, exist_ok=True)
        info = os.stat(src)
        data = open(src, "rb").read()
        tmp = f"{dest}.{os.getpid()}"
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "wb") as fh:
            fh.write(data)
        # A legacy belépő lejárata az mtime-ra épül; a másolás nem friss bejelentkezés.
        os.utime(tmp, ns=(info.st_atime_ns, info.st_mtime_ns))
        os.replace(tmp, dest)
        copied = True
    return copied


def share_mcp_tokens(dest_home, source_home=None):
    """A default profil és a Bot Excellence MCP-belépőjét szinkronizálja: a később lejáró nyer.

    A Hermes MCP és a key_cmd a Bot saját `mcp-tokens/` könyvtárát olvassa. Kétirányú, mert
    az OAuth-szerver frissítéskor elforgatja a refresh tokent: ha a Bot frissített, a default
    profil (és rajta át a többi Bot) régi refresh tokenje már érvénytelen (400). True = a Bot kapott újat.
    """
    source_home = source_home or parent_hermes_home(dest_home)
    if not source_home:
        return False
    src_name = parent_server_name(dest_home, source_home)
    if not src_name:
        return False
    src_dir, dest_dir = os.path.join(source_home, "mcp-tokens"), os.path.join(dest_home, "mcp-tokens")
    src, dest = os.path.join(src_dir, f"{src_name}.json"), os.path.join(dest_dir, f"{SERVER}.json")
    if not os.path.isfile(src):
        return False
    if not os.path.exists(dest) or _expires_at(src) > _expires_at(dest):
        return _copy_login(src_dir, src_name, dest_dir, SERVER)
    # ponytail: a frissítés és a visszamásolás között egy másik Bot még a régi tokennel frissíthet (ritka verseny); akkor újra-belépés.
    if _expires_at(dest) > _expires_at(src):
        _copy_login(dest_dir, SERVER, src_dir, src_name)
    return False


def share_all_mcp_tokens(home):
    """`share_mcp_tokens` a Bot-profilra, vagy a default profilból indulva minden `exc-*` Botra.

    A Hermes asztali app egy folyamatban, `HERMES_HOME=~/.hermes`-szel szolgálja ki az összes
    profilt, így a Guard a default profilt látja; a telepítő is innen indul. Visszaad: kapott-e újat Bot.
    """
    if parent_hermes_home(home):
        return share_mcp_tokens(home)
    profiles = os.path.join(home, "profiles")
    try:
        names = sorted(os.listdir(profiles))
    except OSError:
        return False
    got = False
    for name in names:
        bot = os.path.join(profiles, name)
        if name.startswith("exc-") and os.path.isdir(bot) and not os.path.islink(bot):
            got = share_mcp_tokens(bot, home) or got
    return got


def _expires_at(path):
    """Mikor jár le a belépő? Nagyobb = frissebb a share számára.

    A modern Hermes abszolút ``expires_at``-et ír. Régi / telepítő-másolt fájlokban
    ez hiányzik — a 0-ra esés azt jelentette, hogy egy lejárt, de ``expires_at``-es
    szülő belépő felülírta a Bot friss (expires_at nélküli) loginját. A Hermeshez
    igazodva: hiányzó ``expires_at`` esetén ``mtime + expires_in`` (vagy mtime).
    """
    try:
        data = json.load(open(path, encoding="utf-8"))
        exp = data.get("expires_at")
        if exp is not None and exp != "":
            return float(exp)
        mtime = os.path.getmtime(path)
        extra = data.get("expires_in")
        if extra is not None and extra != "":
            return mtime + float(extra)
        return mtime
    except (OSError, ValueError, TypeError, AttributeError):
        return 0.0


def mcp_access_token(home):
    candidates = [os.path.join(home, "mcp-tokens", f"{SERVER}.json")]
    parent = parent_hermes_home(home)
    name = parent and parent_server_name(home, parent)
    if name:
        candidates.append(os.path.join(parent, "mcp-tokens", f"{name}.json"))
    best, best_exp = None, -1.0
    for path in candidates:
        try:
            tok = json.load(open(path, encoding="utf-8"))["access_token"]
        except (OSError, ValueError, KeyError, TypeError):
            continue
        # A Bot és a default profil közül a később lejáró belépő (a Bot Hermese maga is frissíthet).
        if tok and _expires_at(path) > best_exp:
            best, best_exp = tok, _expires_at(path)
    if best:
        return best
    raise Fail("Jelentkezz be újra a Hermes Excellence-kapcsolatába.")


def fetch(origin, tenant, agent, inst, access):
    req = urllib.request.Request(
        f"{origin}/api/model-gateway/token",
        data=json.dumps({"tenantSlug": tenant, **({"agentId": agent} if agent else {}), "installId": inst}).encode(),
        headers={"Authorization": f"Bearer {access}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            body = json.load(r)
        return body["token"], calendar.timegm(time.strptime(body["expiresAt"][:19], "%Y-%m-%dT%H:%M:%S"))
    except urllib.error.HTTPError as e:
        if e.code == 401:
            raise Fail("Jelentkezz be újra a Hermes Excellence-kapcsolatába.")
        if e.code == 403:
            raise Fail("Ehhez az Excellence-asszisztenshez már nincs hozzáférésed. Kérd a rendszergazdát.")
        raise Fail("Az Excellence modell-átjáró most nem elérhető. Próbáld újra egy perc múlva.")
    except (urllib.error.URLError, OSError, ValueError, KeyError):
        raise Fail("Nem érem el az Excellence szervert. Ellenőrizd az internetkapcsolatot.")


def get_token(home, now=time.time, fetcher=fetch):
    return get_token_exp(home, now, fetcher)[0]


def get_token_exp(home, now=time.time, fetcher=fetch):
    origin, tenant, agent = read_profile(home)
    inst = install_id(home)
    cache = os.path.join(home, CACHE_NAME)
    key = {"tenant": tenant, "agentId": agent, "installId": inst, "origin": origin}
    try:
        c = json.load(open(cache))
        if c["exp"] - LEEWAY > now() and all(c[k] == v for k, v in key.items()):
            return c["token"], c["exp"]
    except (OSError, ValueError, KeyError):
        pass
    # Egy Bot frissítése elforgatja a közös refresh tokent; a Bot-profilból indított szinkron csak a
    # saját párját látja, így a többi Bot lejárt belépővel 401-ezne. Ezért a gyökérből, minden Botra.
    if os.environ.get("EXC_TOKEN_SYNC_ALL", "1") != "0":
        try:
            share_all_mcp_tokens(parent_hermes_home(home) or home)
        except OSError:
            pass  # a szinkron csak segítség, a saját belépővel még próbálkozunk
    token, exp = fetcher(origin, tenant, agent, inst, mcp_access_token(home))
    tmp = f"{cache}.{os.getpid()}"
    try:
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as f:
            json.dump({**key, "token": token, "exp": exp}, f)
        os.replace(tmp, cache)
    except OSError:
        pass  # a cache csak gyorsítás
    return token, exp


def key_cmd_payload(token, exp, now=time.time):
    # JSON `expires_in`-nel: a Hermes bare tokenre 900 s-ot feltételez, a gateway-JWT 600 s → lejárt tokennel 401.
    return json.dumps({"access_token": token, "expires_in": max(1, int(exp - now()))})


def main():
    if sys.argv[1:2] == ["--share"]:
        # Telepítő: a frissen kirakott Bot-profilok az azonos URL-ű default belépőt kapják.
        share_all_mcp_tokens(sys.argv[2] if len(sys.argv) > 2 else default_home())
        return 0
    home = os.environ.get("HERMES_HOME") or default_home()
    try:
        sys.stdout.write(key_cmd_payload(*get_token_exp(home)))
    except Fail as e:
        sys.stderr.write(f"{e}\n")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

exc-guard:
#!/usr/bin/python3 -I
"""exc-guard — fail-closed shell-hook tartalék a `hooks.pre_tool_call`-hoz (#775, H-4, P5).

Külön processz. Minden művelet előtt friss, szerveroldali policyból dönt.
Ha a szerver nem érhető el, Kötött pálya érvényes; a user írható cache-e nem ad engedélyt.
Ha ez a program elszáll, a Hermes
(`fail_closed: true`) blokkolja a toolt. Az allow üres JSON, mert a nem-JSON
stdoutot a fail_closed szintén blokkolná.
"""
import importlib.util
import json
import os
import sys


def user_can_change(path):
    """Az aktuális user módosíthatja vagy törölheti-e a fájlt."""
    if os.name != "nt":
        info = os.stat(path)
        return info.st_uid != 0 or bool(info.st_mode & 0o022)
    # Windowson az st_uid mindig 0: a tényleges ACL-t kérdezzük meg egy írási megnyitással,
    # ami a tartalmat nem módosítja. A könyvtárban a fájl cseréje is módosítás.
    import ctypes
    from ctypes import wintypes
    create = ctypes.WinDLL("kernel32", use_last_error=True).CreateFileW
    create.restype = wintypes.HANDLE
    create.argtypes = [wintypes.LPCWSTR, wintypes.DWORD, wintypes.DWORD, wintypes.LPVOID, wintypes.DWORD, wintypes.DWORD, wintypes.HANDLE]
    close = ctypes.windll.kernel32.CloseHandle
    share, open_existing, backup_semantics = 7, 3, 0x02000000
    checks = (
        (path, 0x40000000 | 0x00010000, 0),  # GENERIC_WRITE | DELETE
        (os.path.dirname(path), 0x2 | 0x40, backup_semantics),  # FILE_ADD_FILE | FILE_DELETE_CHILD
    )
    for target, access, flags in checks:
        handle = create(target, access, share, None, open_existing, flags, None)
        if handle not in (None, wintypes.HANDLE(-1).value):
            close(handle)
            return True
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    return False


def managed_gateway_url(managed_dir):
    path = os.path.join(managed_dir, "config.yaml")
    if user_can_change(path):
        raise ValueError("A céges konfiguráció rendszergazdai tulajdont és írásvédelmet igényel")
    with open(path, encoding="utf-8") as fh:
        in_model = False
        for line in fh:
            if line.strip() and not line.startswith((" ", "#")):
                in_model = line.strip() == "model:"
            if in_model and line.startswith("  base_url:"):
                return json.loads(line.split(":", 1)[1].strip())
    raise ValueError("Hiányzó céges modell-útvonal")


def plugin_dir():
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(here, "excellence-guard"),
        "/opt/excellence/hermes-plugins/excellence-guard",
    ]
    for folder in (here, os.path.join(here, "excellence-guard")):
        path = os.path.join(folder, "excellence_paths.py")
        if os.path.isfile(path):
            spec = importlib.util.spec_from_file_location("excellence_paths_guard", path)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            candidates.append(mod.plugin_dir())
            break
    for path in candidates:
        if os.path.isfile(os.path.join(path, "policy.py")):
            return path
    return None


def main():
    directory = plugin_dir()
    if not directory:
        sys.stderr.write("Az exc-guard nem találja a céges szabálymodult, ezért nem engedek műveletet.\n")
        return 2
    sys.path.insert(0, directory)
    import policy
    import runtime

    raw = sys.stdin.read()
    try:
        payload = json.loads(raw) if raw.strip() else {}
    except json.JSONDecodeError:
        sys.stderr.write("A céges ellenőrzés nem tudta elolvasni a kérést, ezért nem engedem.\n")
        return 2
    if not isinstance(payload, dict):
        payload = {}
    tool = payload.get("tool_name") or ""
    args = payload.get("tool_input") if isinstance(payload.get("tool_input"), dict) else {}
    home = os.environ.get("HERMES_HOME") or runtime.default_home()
    try:
        managed = runtime.managed_dir()
    except runtime.ManagedDirRedirected:
        sys.stdout.write(json.dumps({
            "action": "block",
            "message": "A Hermes nem a céges beállítást használja. Zárd be, és nyisd meg újra. Ha így is előjön, szólj a rendszergazdának.",
        }, ensure_ascii=False) + "\n")
        return 0
    try:
        token_helper = runtime.load_exc_token()
        origin = token_helper.read_profile(home)[0] if token_helper else None
        expected = origin + "/api/model-gateway/v1" if origin else None
        if not policy.is_excellence_route("excellence", managed_gateway_url(managed), expected):
            raise ValueError("A profil nem a céges modell-útvonalhoz tartozik")
        status, snapshot = runtime.fetch_snapshot(home)
    except Exception:
        status, snapshot = "down", None
    interpreted = {"kind": "snapshot", "snapshot": snapshot} if status == "ok" else {"kind": "revoked" if status == "revoked" else "bound"}
    decision = policy.decide_interpreted(interpreted, tool, args, os.path.join(home, "attachments"))
    sys.stdout.write(json.dumps(policy.hook_body(decision), ensure_ascii=False) + "\n")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.stderr.write("A céges ellenőrzés hibázott, ezért ezt a műveletet nem engedem.\n")
        sys.exit(2)

excellence-guard/policy.py:
"""Excellence Guard döntés (#775, spec §5.2, §9 R2/R4, D4).

Tiszta: nincs hálózat, nincs óra. A snapshot a V1-1 `GET /api/client-policy/snapshot`
alakja. Explicit tool-szabály (allow/approve/deny) előbb; ha nincs találat, a
képesség szintje dönt. Ismeretlen MCP-szerver company_only és plus_approved mellett
blokkol (U1). Hibás vagy hiányzó snapshot helyett a Kötött pálya preset.
"""
import os
import re
from urllib.parse import urlsplit

GUARD_VERSION = "0.3.1"
NOTICE = "Ez a munkatárs céges módban fut, a beszélgetéseid naplózásra kerülnek."
ASK = "Ha erre szükséged van, kérd a rendszergazdát."
OFFLINE_TTL_SECONDS = 3600
REVALIDATE_SECONDS = 15

# A V1-1 presetek képességszintjei (content_filter nélkül — az a gatewayé).
BOUND = {
    "code_execution": "denied",
    "local_files": "none",
    "browser": "denied",
    "web_search": "denied",
    "mcp_servers": "company_only",
    "skills": "approved_only",
    "local_memory": "excellence",
    "autonomous_run": "denied",
    "human_approval": "risky",
    "audit_depth": "plus_tool_results",
    "external_services": "denied",
}
STANDARD = {
    **BOUND,
    "code_execution": "sandbox_only",
    "local_files": "read_only",
    "browser": "domain_allowlist",
    "web_search": "company_egress",
    "mcp_servers": "plus_approved",
    "autonomous_run": "audited",
    "audit_depth": "prompt_and_response",
}
FREE = {
    **BOUND,
    "code_execution": "local_free",
    "local_files": "project_write",
    "browser": "free",
    "web_search": "builtin",
    "mcp_servers": "plus_approved",
    "skills": "plus_own_audited",
    "local_memory": "local",
    "autonomous_run": "audited",
    "human_approval": "none",
    "audit_depth": "prompt_and_response",
    "external_services": "allowed",
}

_RULE_RANK = {"allow": 0, "approve": 1, "deny": 2}

# #872: offline tartalék-katalógus (D4). Élesben a snapshot `toolCatalog`-ja dönt; ez a lista
# a szerver `DEFAULT_TOOL_CATALOG`-ja (tool-catalog.ts), a client-policy-tool-catalog teszt veti össze.
# #871/D17: a híd (`passthrough`) és a beszélgetés (`always`) nem döntési pont.
FALLBACK_CATALOG = [
    ("tool_search", "passthrough"), ("tool_describe", "passthrough"), ("tool_call", "passthrough"),
    ("clarify", "always"), ("todo_list", "always"), ("todo", "always"), ("gui_tour", "always"),
    ("show_tip", "always"), ("apply_layout", "always"), ("focus_pane", "always"),
    ("desktop_project", "always"), ("react_to_message", "always"), ("setup_choose", "always"),
    ("terminal", "capability:code_execution:run"), ("process_manage", "capability:code_execution:run"),
    ("execute_code", "capability:code_execution:run"), ("read_terminal", "capability:code_execution:run"),
    ("close_terminal", "capability:code_execution:run"),
    ("read_file", "capability:local_files:read"), ("search_files", "capability:local_files:read"),
    ("vision_analyze", "capability:local_files:read"),
    ("write_file", "capability:local_files:write"), ("patch", "capability:local_files:write"),
    ("browser_*", "capability:browser:use"), ("computer_use", "capability:browser:use"),
    ("desktop_preview", "capability:browser:use"), ("drive_preview", "capability:browser:use"),
    ("annotate_preview", "capability:browser:use"), ("read_window_below", "capability:browser:use"),
    ("web_search", "capability:web_search:use"), ("web_extract", "capability:web_search:use"),
    ("x_search", "capability:web_search:use"),
    ("memory", "capability:local_memory:use"), ("session_search", "capability:local_memory:use"),
    ("skills_list", "capability:skills:read"), ("skill_view", "capability:skills:read"),
    ("skill_manage", "capability:skills:write"), ("manage_catalog", "capability:skills:write"),
    ("delegate_task", "capability:autonomous_run:use"), ("cronjob_manage", "capability:autonomous_run:use"),
    ("kanban_*", "capability:autonomous_run:use"), ("start_chat", "capability:autonomous_run:use"),
    ("image_generate", "capability:external_services:use"), ("video_generate", "capability:external_services:use"),
    ("xai_video_edit", "capability:external_services:use"), ("xai_video_extend", "capability:external_services:use"),
    ("text_to_speech", "capability:external_services:use"), ("manage_connections", "capability:external_services:use"),
    ("video_analyze", "capability:external_services:use"), ("discord", "capability:external_services:use"),
    ("discord_admin", "capability:external_services:use"), ("feishu_doc_read", "capability:external_services:use"),
    ("feishu_drive_*", "capability:external_services:use"), ("yb_*", "capability:external_services:use"),
    ("mcp__*", "mcp"),
]
# (tengely, művelet) → a Guard belső döntési fajtája
_KIND = {
    ("code_execution", "run"): "code",
    ("local_files", "read"): "file_read",
    ("local_files", "write"): "file_write",
    ("browser", "use"): "browser",
    ("web_search", "use"): "web",
    ("local_memory", "use"): "memory",
    ("skills", "read"): "skill_read",
    ("skills", "write"): "skill_write",
    ("autonomous_run", "use"): "autonomous",
    ("external_services", "use"): "external",
}
# #873: „csak csatolmány” mellett ezekből az argumentumokból jön az olvasott útvonal.
_PATH_ARGS = {"read_file": "path", "search_files": "path", "vision_analyze": "image_url"}


class Decision:
    def __init__(self, action, message, capability=None, level=None, unclassified=False):
        self.action = action  # allow | approve | block
        self.message = message
        self.capability = capability
        self.level = level
        # #872: a katalógus nem ismeri az eszközt → `tool_unclassified` esemény az adminnak.
        self.unclassified = unclassified

    def __repr__(self):
        return f"Decision({self.action!r}, {self.message!r})"


def bound_snapshot():
    return {
        "capabilities": dict(BOUND),
        "toolRules": [],
        "reasons": {key: {"source": "offline"} for key in BOUND},
        "policyVersion": "offline-bound",
    }


def snapshot_of(capabilities, tool_rules=(), version="test", source="user_preset"):
    return {
        "capabilities": dict(capabilities),
        "toolRules": list(tool_rules),
        "reasons": {key: {"source": source} for key in capabilities},
        "policyVersion": version,
    }


def sanitize_mcp_component(value):
    """Ugyanaz, mint a Hermes `sanitize_mcp_name_component`: nem [A-Za-z0-9_] → `_`."""
    return re.sub(r"[^A-Za-z0-9_]", "_", str(value or ""))


def mcp_server(tool_name):
    if not isinstance(tool_name, str) or not tool_name.startswith("mcp__"):
        return None
    server, sep, _tool = tool_name[5:].partition("__")
    return server if sep and server else None


def tool_origin(tool_name):
    return "mcp" if isinstance(tool_name, str) and tool_name.startswith("mcp__") else "local"


def company_servers():
    # Environment variables are controlled by the caller, not the company policy.
    return {"excellence"}


def catalog_of(snapshot):
    """A snapshot katalógusa [(minta, osztály)]; régi vagy hibás snapshotnál a beépített tartalék."""
    raw = (snapshot or {}).get("toolCatalog")
    if not isinstance(raw, list):
        return FALLBACK_CATALOG
    out = []
    for entry in raw:
        if isinstance(entry, dict) and isinstance(entry.get("pattern"), str) and isinstance(entry.get("class"), str):
            out.append((entry["pattern"], entry["class"]))
    return out


def tool_class(catalog, tool_name):
    """Pontos név előbb, utána a leghosszabb `*` végű minta (mint a szerver `classifyTool`-ja). None = besorolatlan."""
    best = None
    for pattern, cls in catalog:
        if pattern == tool_name:
            return cls
        if pattern.endswith("*") and tool_name.startswith(pattern[:-1]) and (best is None or len(pattern) > len(best[0])):
            best = (pattern, cls)
    return best[1] if best else None


def _classify(tool_name, catalog=FALLBACK_CATALOG):
    """(képesség, fajta). Fajta: a _KIND értékei, mcp, passthrough, always, denied, external, other."""
    cls = tool_class(catalog, tool_name)
    if cls is None:
        return None, "other"
    if cls == "mcp":
        return "mcp_servers", "mcp"
    if cls in ("passthrough", "always", "denied"):
        return None, cls
    parts = cls.split(":")
    if len(parts) == 3 and parts[0] == "capability":
        kind = _KIND.get((parts[1], parts[2]))
        # Ismert osztály, de a Guard még nem ismeri a tengelyét: szigorúan tilt.
        return parts[1], kind or "unknown_axis"
    return None, "other"


def _pattern(pattern):
    body = ".*".join(re.escape(part) for part in str(pattern).split("*"))
    return re.compile(f"^{body}$")


def matching_rule(rules, tool_name):
    """Az összes illeszkedő szabály közül a legszigorúbb (tiltás nyer)."""
    found = None
    for rule in rules or []:
        pattern = rule.get("pattern") if isinstance(rule, dict) else None
        action = rule.get("action") if isinstance(rule, dict) else None
        if not pattern or action not in _RULE_RANK:
            continue
        if _pattern(pattern).match(tool_name):
            found = action if found is None or _RULE_RANK[action] > _RULE_RANK[found] else found
    return found


def _why(source):
    if source == "offline":
        return "Az Excellence szerver most nem elérhető, ezért a szigorúbb, kötött pályás szabály érvényes."
    if source == "agent_ceiling":
        return "Ez az asszisztens nem erre való."
    if source in ("user_preset", "user_override"):
        return "A te céges beállításod ezt nem engedi."
    return "A céges szabály ezt nem engedi."


def _lead(kind, level, tool_name):
    server = mcp_server(tool_name)
    if kind == "mcp":
        shown = server or "ismeretlen"
        return f"A(z) „{shown}” külső eszköz nincs a céges listán, ezért a(z) „{tool_name}” hívás nem fut le. A céges Excellence-eszközök engedettek."
    if kind == "code" and level == "sandbox_only":
        return "A kódot csak a céges homokozóban futtathatod, a saját gépeden nem."
    if kind == "code":
        return "Ezzel az asszisztenssel nem futtathatsz parancsot vagy kódot a gépeden."
    if kind in ("file_read", "file_write") and level == "attachments_only":
        if kind == "file_write":
            return "A chatbe csatolt fájlt elolvashatod, de helyi fájlt írni vagy módosítani nem."
        return "Ezzel az asszisztenssel csak a chatbe csatolt fájlt nyithatod meg (csak csatolmány szabály), a gépen lévő más fájlt nem. Csatold a fájlt a beszélgetéshez."
    if kind == "file_read" or (kind == "file_write" and level == "none"):
        return "Ezzel az asszisztenssel nem nyithatsz helyi fájlt."
    if kind == "file_write":
        if level == "project_write":
            return "A jóváhagyott projektmappa nincs megadva, ezért a helyi fájlmódosítást nem engedem. Helyi fájlt olvasni viszont engedett."
        return "Fájlt olvashatsz, de írni vagy módosítani nem."
    if kind == "browser" and level == "company_cloud":
        return "A helyi böngésző nincs engedve. A céges böngésző ehhez az asszisztenshez még nem elérhető."
    if kind == "browser":
        if level == "domain_allowlist":
            return "A megengedett weboldalak céges listája nincs megadva, ezért a böngészőt nem engedem."
        return "A böngészőt ez a beállítás nem engedi."
    if kind == "web":
        return "A beépített webes keresés ki van kapcsolva."
    if kind == "memory":
        if level == "excellence":
            return "A céges memóriát az Excellence-eszközökön keresztül használd; a gépen tárolt memória ehhez az asszisztenshez nincs engedve."
        return "A helyi memória ki van kapcsolva."
    if kind == "autonomous":
        return "Önálló háttérfutást (másik asszisztens vagy időzített feladat) ez a beállítás nem enged."
    if kind == "skill_write":
        return "Új vagy módosított skillt ez a beállítás nem enged. Csak a jóváhagyott skillek használhatók."
    if kind == "skill_read":
        return "A jóváhagyott skillek ellenőrizhető céges listája még nem érhető el, ezért helyi skillt nem tölthetek be."
    if kind == "external":
        return "Ez a Hermes saját felhős szolgáltatása (például kép-, hang- vagy videókészítés, külső fiók), amely a céges modell-útvonalat megkerüli, ezért nincs engedve."
    if kind == "denied":
        return f"A(z) „{tool_name}” eszközt a cég véglegesen letiltotta."
    return f"A(z) „{tool_name}” eszközt a céges lista még nem ismeri, ezért nem fut le. A rendszergazda a besorolatlan eszközök között látja."


def _block(kind, level, tool_name, source, capability):
    # Ismeretlen vagy véglegesen tiltott eszköznél nincs szintbeli döntés, amire hivatkozhatnánk (#871).
    why = "" if kind in ("other", "denied", "unknown_axis") else f" {_why(source)}"
    text = f"{_lead(kind, level, tool_name)}{why} {ASK}"
    return Decision("block", text, capability, level, unclassified=kind == "other")


def _approve(tool_name, capability, level, because):
    return Decision(
        "approve",
        f"A(z) „{tool_name}” csak a jóváhagyásoddal fut le. {because}",
        capability,
        level,
    )


def _is_risky(kind):
    return kind in {"code", "file_write", "browser", "autonomous", "skill_write", "mcp"}


def in_attachments(path, attachments_dir):
    """#873: a csatolmány-mappán belüli útvonal, symlinkek feloldása után. A relatív nevet a mappa alatt értjük."""
    if not attachments_dir or not isinstance(path, str) or not path:
        return False
    try:
        base = os.path.expanduser(attachments_dir)
        raw = os.path.expanduser(path)
        if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", raw):
            return False  # URL / data: URI nem helyi fájl (#873: szándékosan blokkolt)
        if not os.path.isabs(raw):
            raw = os.path.join(base, raw)
        if ".." in re.split(r"[\\/]", raw):
            return False
        root = os.path.normcase(os.path.realpath(base))
        target = os.path.normcase(os.path.realpath(raw))
        return os.path.commonpath([root, target]) == root
    except (ValueError, OSError):
        return False


def _capability_action(kind, level, tool_name, args=None, attachments_dir=None):
    if kind == "code":
        if level in ("denied", "sandbox_only"):
            return "block"
        if level == "local_with_approval":
            return "approve"
        return "allow"
    if kind == "file_read":
        if level == "attachments_only":
            path = (args or {}).get(_PATH_ARGS.get(tool_name, "path"))
            return "allow" if in_attachments(path, attachments_dir) else "block"
        return "block" if level == "none" else "allow"
    if kind == "file_write":
        return "allow" if level == "free" else "block"
    if kind == "browser":
        if level in ("denied", "company_cloud", "domain_allowlist"):
            return "block"
        return "allow"
    if kind == "web":
        return "block" if level in ("denied", "company_egress") else "allow"
    if kind == "memory":
        return "allow" if level == "local" else "block"
    if kind == "autonomous":
        return "block" if level == "denied" else "allow"
    if kind == "external":
        return "allow" if level == "allowed" else "block"
    if kind == "skill_write":
        return "block" if level == "approved_only" else "allow"
    if kind == "skill_read":
        if tool_name == "skill_view" and level == "approved_only":
            return "block"
        return "allow"
    if kind == "mcp":
        if level == "free":
            return "allow"
        server = mcp_server(tool_name)
        if server and sanitize_mcp_component(server) in company_servers():
            return "allow"
        return "block"
    # R2: ami nincs a katalógusban, az nincs engedve (explicit toolRules előbb nyer).
    return "block"


def decide(snapshot, tool_name, args=None, attachments_dir=None):
    """allow / approve / block. Az args csak a „csak csatolmány” útvonal-döntéshez kell (#873).

    `attachments_dir`: a Bot-profil `attachments/` mappája; hiányában a csatolmány-szint mindent tilt.
    """
    if not isinstance(tool_name, str) or not tool_name:
        return Decision("block", f"Nem látom, milyen művelet indulna, ezért nem engedem. {ASK}")
    caps = (snapshot or {}).get("capabilities")
    if not isinstance(caps, dict):
        snapshot = bound_snapshot()
        caps = snapshot["capabilities"]
    capability, kind = _classify(tool_name, catalog_of(snapshot))
    if kind == "denied":  # a tiltás nyer, eszközönkénti engedély sem oldja fel
        return _block(kind, None, tool_name, None, None)
    level = caps.get(capability) if capability else None
    if capability and not isinstance(level, str):
        level = BOUND.get(capability)
    source = ((snapshot.get("reasons") or {}).get(capability) or {}).get("source") or "tenant_default"

    rule = matching_rule((snapshot or {}).get("toolRules"), tool_name)
    if rule == "deny":
        return Decision(
            "block",
            f"A(z) „{tool_name}” műveletet a céges szabály tiltja. {_why(source)} {ASK}",
            capability,
            level,
        )
    if rule == "approve":
        return _approve(tool_name, capability, level, "A céges szabály jóváhagyáshoz köti.")
    if rule == "allow":
        return Decision("allow", "", capability, level)

    # #871: híd/beszélgetés átlátszó — de csak ha nincs explicit toolRules találat.
    # A tiltás mindig nyer (D3); a human_approval alól viszont kivétel, mert a
    # kockázat a hívott belső eszközé, azt a saját pre_tool_call-ja dönti el.
    if kind in ("passthrough", "always"):
        return Decision("allow", "", capability, level)

    action = _capability_action(kind, level, tool_name, args if isinstance(args, dict) else None, attachments_dir)
    if action == "block":
        return _block(kind, level, tool_name, source, capability)
    if action == "approve":
        because = "A beállítás ezt csak jóváhagyással engedi."
        if kind == "browser" and level == "domain_allowlist":
            because = "A megengedett oldalak listája nélkül nem engedem szabadon a böngészőt."
        return _approve(tool_name, capability, level, because)

    approval = caps.get("human_approval") or "risky"
    if approval == "always" or (approval == "risky" and _is_risky(kind)):
        return _approve(tool_name, capability, level, "A céges szabály a kockázatos műveletet jóváhagyáshoz köti.")
    return Decision("allow", "", capability, level)


def decide_interpreted(interpreted, tool_name, args=None, attachments_dir=None):
    """A cache-értelmezés eredménye: revoked / bound / snapshot."""
    kind = (interpreted or {}).get("kind")
    if kind == "revoked":
        return Decision(
            "block",
            "Ehhez az asszisztenshez már nincs hozzáférésed, ezért semmilyen műveletet nem engedek. Kérd a rendszergazdát.",
        )
    if kind == "bound":
        return decide(bound_snapshot(), tool_name, args, attachments_dir)
    return decide((interpreted or {}).get("snapshot"), tool_name, args, attachments_dir)


def interpret_cache(state, now, offline_ttl=OFFLINE_TTL_SECONDS):
    """A lemezen lévő snapshot. Érvényes 1 óráig (D4), utána Kötött pálya. Visszavonás azonnal blokkol."""
    if not isinstance(state, dict):
        return {"kind": "bound"}
    if state.get("revoked"):
        return {"kind": "revoked"}
    cached_at = state.get("cachedAt")
    snap = state.get("snapshot")
    if not isinstance(cached_at, (int, float)) or not isinstance(snap, dict) or not isinstance(snap.get("capabilities"), dict):
        return {"kind": "bound"}
    if now - cached_at >= offline_ttl:
        return {"kind": "bound"}
    return {"kind": "snapshot", "snapshot": snap}


def hook_body(decision):
    """Hermes pre_tool_call / shell-hook válasz. Az allow `{}`: a fail_closed a nem-JSON stdoutot blokkolná."""
    if decision.action == "allow":
        return {}
    if decision.action == "approve":
        return {"action": "approve", "message": decision.message, "rule_key": "excellence-guard"}
    return {"action": "block", "message": decision.message}


def keep_content(depth, kind, content):
    """A szerver is eldobja, ami a mélységen kívül esik; ide se küldjük a promptot, ha nem kell."""
    rank = {"metadata": 0, "prompt_and_response": 1, "plus_tool_results": 2}
    need = 2 if kind == "tool_call" else 1
    if rank.get(depth, 0) < need:
        return None
    return content


def is_excellence_route(provider, base_url, expected_base_url=None):
    # Hermes named providers resolve to `custom` before execution middleware runs.
    if str(provider or "").strip().lower() not in {"excellence", "custom"}:
        return False
    def endpoint(value):
        url = urlsplit(str(value or "").strip())
        if url.scheme not in {"http", "https"} or not url.hostname or url.username is not None or url.password is not None or url.query or url.fragment:
            return None
        return url.scheme, url.hostname, url.port or (443 if url.scheme == "https" else 80), url.path.rstrip("/")
    try:
        actual, expected = endpoint(base_url), endpoint(expected_base_url)
        return expected is not None and actual == expected
    except ValueError:
        return False


# A session `/model --provider openrouter` (K4) a fő hívást és a title_generation
# mellékhívást is ezekre a hostokra viszi. A Guard HTTP-kapu ezeket blokkolja.
FOREIGN_LLM_HOSTS = frozenset({
    "openrouter.ai",
    "api.openai.com",
    "api.anthropic.com",
    "api.groq.com",
    "api.together.xyz",
    "api.together.ai",
    "api.fireworks.ai",
    "api.deepseek.com",
    "api.mistral.ai",
    "api.moonshot.ai",
    "api.x.ai",
    "generativelanguage.googleapis.com",
    "api.deepinfra.com",
    "api.nscale.com",
})

_LLM_PATH_MARKERS = (
    "/chat/completions",
    "/v1/messages",
    "/v1/responses",
    "/api/v1/models",
    "/v1/models",
)


def hostname_of(url):
    try:
        return (urlsplit(str(url or "")).hostname or "").strip().lower().rstrip(".")
    except ValueError:
        return ""


def _host_matches(host, allowed):
    return bool(host) and bool(allowed) and (host == allowed or host.endswith("." + allowed))


def is_foreign_llm_host(host):
    return any(_host_matches(host, blocked) for blocked in FOREIGN_LLM_HOSTS)


def should_block_llm_egress(url, expected_gateway_url=None):
    """True, ha a kérés külső modell-API-ra menne a céges Gateway helyett (K4)."""
    host = hostname_of(url)
    if not host:
        return False
    try:
        actual = urlsplit(str(url or ""))
        gateway = urlsplit(str(expected_gateway_url or ""))
        if (host == hostname_of(expected_gateway_url)
                and actual.scheme == gateway.scheme
                and (actual.port or (443 if actual.scheme == "https" else 80))
                == (gateway.port or (443 if gateway.scheme == "https" else 80))
                and actual.path.startswith(gateway.path.rstrip("/") + "/")):
            return False
    except ValueError:
        pass
    if is_foreign_llm_host(host):
        return True
    try:
        path = urlsplit(str(url or "")).path.lower()
    except ValueError:
        return False
    return any(marker in path for marker in _LLM_PATH_MARKERS)


PROVIDER_BLOCK = (
    "Ez a hívás nem a céges Excellence modellen menne, ezért megállítottam. "
    "Céges módban csak az Excellence modell használható, különben a beszélgetés kiesne a naplóból. "
    "Szólj a rendszergazdának, ha másik modell kell."
)

excellence-guard/runtime.py:
"""Snapshot-cache, audit-sor, heartbeat, plugin-életciklus (#775). Csak stdlib.

A shell-hook (`exc-guard`) ugyanezt a cache-fájlt olvassa, hálózat nélkül.
A managed-dir hash kanonikus alakja megegyezik a V1-8 `managedDirHash`-ével
(`excellence-managed-dir-v1`), hogy a szerver el tudja dönteni az eltérést.
"""
import hashlib
import importlib.util
from importlib.machinery import SourceFileLoader
import json
import logging
import os
import subprocess
import sys
import threading
import time
import urllib.error
import urllib.request
import uuid
from types import SimpleNamespace

import policy

log = logging.getLogger("excellence_guard")

CACHE_FILE = ("excellence-guard", "snapshot.json")
QUEUE_FILE = ("excellence-guard", "audit-queue.jsonl")
MANAGED_FILES = ("config.yaml", ".env", "excellence-install-id")
HASH_VERSION = "excellence-managed-dir-v1"
MAX_CONTENT_CHARS = 200_000


def _load_paths():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "excellence_paths.py")
    spec = importlib.util.spec_from_file_location("excellence_paths_runtime", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


_paths = _load_paths()
ManagedDirRedirected = _paths.ManagedDirRedirected
DEFAULT_MANAGED_DIR = _paths.default_managed_dir()
TOKEN_HELPER_PATH = _paths.token_helper_path()
_lock = threading.Lock()
# Gyakrabban, mint az exc-token 60 s-os LEEWAY-e: a fejlécben sosem marad lejárt JWT.
TOKEN_REFRESH_SECONDS = 30

# K4: a session `/model --provider` kikerüli az `llm_execution` middleware-t a
# title_generation mellékhívásnál. A HTTP-kapu a tényleges kérés előtt állít meg.
_EGRESS = {
    "open": None,
    "httpx_send": None,
    "httpx_asend": None,
    "expected": lambda: None,
    "aux_patched": False,
}


class ForeignLlmRoute(urllib.error.URLError):
    """Külső modell-API a céges Gateway helyett. Az opener/httpx nem fut le."""

    def __init__(self, url):
        super().__init__(policy.PROVIDER_BLOCK)
        self.url = url


def _url_of(fullurl):
    if hasattr(fullurl, "full_url"):
        return str(fullurl.full_url)
    if hasattr(fullurl, "url"):
        return str(fullurl.url)
    return str(fullurl)


def expected_gateway_url(home):
    try:
        mod = load_exc_token()
        if mod is None:
            return None
        return mod.read_profile(home)[0] + "/api/model-gateway/v1"
    except Exception:
        return None


def run_gated_auxiliary_call(call, *, provider, base_url, expected_url):
    """Mellékhívás (title_generation, compression, …) a Guard útvonal-ellenőrzése után."""
    if not policy.is_excellence_route(provider, base_url, expected_url):
        raise ForeignLlmRoute(base_url or provider)
    return call()


def install_llm_egress_gate(expected_url_fn):
    """urllib + httpx: külső LLM-host/útvonal kérése nem indul el. Idempotens."""
    _EGRESS["expected"] = expected_url_fn
    if _EGRESS["open"] is None:
        _EGRESS["open"] = urllib.request.OpenerDirector.open

        def open_gated(self, fullurl, *args, **kwargs):
            url = _url_of(fullurl)
            if policy.should_block_llm_egress(url, _EGRESS["expected"]()):
                raise ForeignLlmRoute(url)
            return _EGRESS["open"](self, fullurl, *args, **kwargs)

        urllib.request.OpenerDirector.open = open_gated
    try:
        import httpx
    except ImportError:
        return
    # A send() belső redirect-ciklusa nem hívja újra a send()-et: minden HTTP-kérésnél zárunk.
    if _EGRESS["httpx_send"] is None:
        _EGRESS["httpx_send"] = httpx.Client._send_single_request

        def send_gated(self, request, *args, **kwargs):
            url = str(getattr(request, "url", request))
            if policy.should_block_llm_egress(url, _EGRESS["expected"]()):
                raise httpx.RequestError(policy.PROVIDER_BLOCK, request=request)
            return _EGRESS["httpx_send"](self, request, *args, **kwargs)

        httpx.Client._send_single_request = send_gated
    if _EGRESS["httpx_asend"] is None and hasattr(httpx, "AsyncClient"):
        _EGRESS["httpx_asend"] = httpx.AsyncClient._send_single_request

        async def asend_gated(self, request, *args, **kwargs):
            url = str(getattr(request, "url", request))
            if policy.should_block_llm_egress(url, _EGRESS["expected"]()):
                raise httpx.RequestError(policy.PROVIDER_BLOCK, request=request)
            return await _EGRESS["httpx_asend"](self, request, *args, **kwargs)

        httpx.AsyncClient._send_single_request = asend_gated


def uninstall_llm_egress_gate():
    if _EGRESS["open"] is not None:
        urllib.request.OpenerDirector.open = _EGRESS["open"]
        _EGRESS["open"] = None
    try:
        import httpx
    except ImportError:
        httpx = None
    if httpx is not None and _EGRESS["httpx_send"] is not None:
        httpx.Client._send_single_request = _EGRESS["httpx_send"]
        _EGRESS["httpx_send"] = None
    if httpx is not None and _EGRESS["httpx_asend"] is not None:
        httpx.AsyncClient._send_single_request = _EGRESS["httpx_asend"]
        _EGRESS["httpx_asend"] = None
    _EGRESS["expected"] = lambda: None


def patch_auxiliary_hooks(expected_url_fn):
    """A Hermes aux funnel (`run_with_aux_hooks`) a `call()` előtt fail-closed."""
    try:
        import agent.auxiliary_hooks as aux
    except ImportError:
        return False
    aux._excellence_guard_expected = expected_url_fn
    if getattr(aux, "_excellence_guard_gated", False):
        return True
    orig = aux.run_with_aux_hooks
    orig_async = aux.arun_with_aux_hooks

    def gated(call, **kwargs):
        client = kwargs.get("client")
        base_url = str(getattr(client, "base_url", "") or "")
        return run_gated_auxiliary_call(
            lambda: orig(call, **kwargs),
            provider=kwargs.get("provider"),
            base_url=base_url,
            expected_url=aux._excellence_guard_expected(),
        )

    async def gated_async(call, **kwargs):
        client = kwargs.get("client")
        base_url = str(getattr(client, "base_url", "") or "")
        if not policy.is_excellence_route(kwargs.get("provider"), base_url, aux._excellence_guard_expected()):
            raise ForeignLlmRoute(base_url or kwargs.get("provider"))
        return await orig_async(call, **kwargs)

    aux.run_with_aux_hooks = gated
    aux.arun_with_aux_hooks = gated_async
    aux._excellence_guard_gated = True
    _EGRESS["aux_patched"] = True
    return True


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def managed_dir_hash(files):
    body = "".join(f"{name}\n{sha256_bytes(files.get(name, b''))}\n" for name in MANAGED_FILES)
    body_bytes = f"{HASH_VERSION}\n{body}".encode()
    return sha256_bytes(body_bytes)


def hash_managed_dir(path):
    files = {}
    for name in MANAGED_FILES:
        try:
            with open(os.path.join(path, name), "rb") as fh:
                files[name] = fh.read()
        except OSError:
            files[name] = b""
    return managed_dir_hash(files)


def config_hash(home):
    try:
        with open(os.path.join(home, "config.yaml"), "rb") as fh:
            data = fh.read()
    except OSError:
        data = b"missing"
    return sha256_bytes(data)


def managed_dir():
    return _paths.resolve_managed_dir(os.environ.get("HERMES_MANAGED_DIR"), os.name == "nt")


def default_home():
    return _paths.default_home()


def reported_managed_dir_hash():
    """A heartbeat hash-e. Átirányított Windows-padlónál szándékosan nem egyezik a kiadottal."""
    try:
        return hash_managed_dir(managed_dir())
    except ManagedDirRedirected:
        return "redirected"


def _under(home, parts):
    return os.path.join(home, *parts)


def read_json(path):
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except (OSError, ValueError):
        return None


def write_json(path, payload):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = f"{path}.{os.getpid()}.{uuid.uuid4().hex}"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as fh:
        json.dump(payload, fh)
    os.replace(tmp, path)


def load_exc_token():
    here = os.path.dirname(os.path.abspath(__file__))
    candidates = [
        os.path.join(here, "..", "exc_token.py"),
        TOKEN_HELPER_PATH,
    ]
    for path in candidates:
        if not os.path.isfile(path):
            continue
        spec = importlib.util.spec_from_file_location("exc_token_guard", path, loader=SourceFileLoader("exc_token_guard", path))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod
    return None


def fetch_snapshot(home):
    """('ok', snapshot) | ('revoked', None) | ('down', None). A 401/403 visszavonás, nem D4."""
    if os.environ.get("EXC_GUARD_OFFLINE") == "1":
        return "down", None
    mod = load_exc_token()
    if mod is None:
        return "down", None
    try:
        token = mod.get_token(home)
        origin, _tenant, _agent = mod.read_profile(home)
    except mod.Fail as exc:
        text = str(exc)
        if "nincs hozzáférésed" in text or "Jelentkezz be" in text:
            return "revoked", None
        return "down", None
    req = urllib.request.Request(
        f"{origin}/api/client-policy/snapshot",
        headers={"Authorization": f"Bearer {token}"},
    )
    try:
        with urllib.request.urlopen(req, timeout=5) as response:
            body = json.load(response)
        if isinstance(body, dict) and isinstance(body.get("capabilities"), dict):
            return "ok", body
        return "down", None
    except urllib.error.HTTPError as exc:
        if exc.code in (401, 403):
            return "revoked", None
        return "down", None
    except (urllib.error.URLError, OSError, ValueError):
        return "down", None


class SnapshotClient:
    def __init__(self, home, fetcher=None, now=time.time, revalidate=policy.REVALIDATE_SECONDS, offline_ttl=policy.OFFLINE_TTL_SECONDS):
        self.home = home
        self.fetcher = fetcher or (lambda: fetch_snapshot(home))
        self.now = now
        self.revalidate = revalidate
        self.offline_ttl = offline_ttl

    def path(self):
        return _under(self.home, CACHE_FILE)

    def read(self):
        return read_json(self.path())

    def refresh(self, force=False):
        now = self.now()
        state = self.read()
        fresh = (
            not force
            and isinstance(state, dict)
            and isinstance(state.get("cachedAt"), (int, float))
            and now - state["cachedAt"] < self.revalidate
            and isinstance(state.get("snapshot"), dict)
            and not state.get("revoked")
        )
        if fresh:
            return policy.interpret_cache(state, now, self.offline_ttl)
        status, snap = self.fetcher()
        if status == "ok":
            write_json(self.path(), {"cachedAt": now, "revoked": False, "snapshot": snap, "agentId": snap.get("agentId")})
            return {"kind": "snapshot", "snapshot": snap}
        if status == "revoked":
            write_json(self.path(), {"cachedAt": now, "revoked": True, "snapshot": None})
            return {"kind": "revoked"}
        return policy.interpret_cache(state, now, self.offline_ttl)


def _clip(value):
    if value is None:
        return None
    if isinstance(value, str):
        raw = value.encode("utf-8")
        if len(raw) <= MAX_CONTENT_CHARS:
            return value
        return raw[:MAX_CONTENT_CHARS].decode("utf-8", errors="ignore") + "… [levágva]"
    text = json.dumps(value, ensure_ascii=False, default=str)
    if len(text.encode("utf-8")) <= MAX_CONTENT_CHARS:
        return value
    return text.encode("utf-8")[:MAX_CONTENT_CHARS].decode("utf-8", errors="ignore") + "… [levágva]"


def build_event(snapshot, session_id, turn_id, kind, content, meta):
    depth = ((snapshot or {}).get("capabilities") or {}).get("audit_depth") or "metadata"
    kept = policy.keep_content(depth, kind, content)
    event = {
        "id": str(uuid.uuid4()),
        "sessionId": (session_id or "unknown")[:200],
        "kind": kind,
        "meta": meta or {},
    }
    if turn_id:
        event["turnId"] = str(turn_id)[:200]
    if kept is not None:
        event["content"] = _clip(kept)
    return event


def enqueue(home, event):
    path = _under(home, QUEUE_FILE)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    line = json.dumps(event, ensure_ascii=False)
    with _lock:
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        with os.fdopen(fd, "a", encoding="utf-8") as fh:
            fh.write(line + "\n")


def _read_queue(path):
    try:
        with open(path, encoding="utf-8") as fh:
            lines = fh.read().splitlines()
    except OSError:
        return []
    events = []
    for line in lines:
        if not line.strip():
            continue
        try:
            events.append(json.loads(line))
        except ValueError:
            continue
    return events


def write_json_lines(path, events):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = f"{path}.{os.getpid()}"
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as fh:
        for event in events:
            fh.write(json.dumps(event, ensure_ascii=False) + "\n")
    os.replace(tmp, path)


def flush_queue(home, post, limit=100):
    """post(events) → 'ok' | 'drop' | 'retry'. Az ok és a drop is kiveszi a feladott id-ket."""
    path = _under(home, QUEUE_FILE)
    with _lock:
        events = _read_queue(path)
    if not events:
        return 0
    batch = events[:limit]
    outcome = post(batch)
    if outcome == "retry":
        return 0
    sent = {event.get("id") for event in batch}
    with _lock:
        current = _read_queue(path)
        keep = [event for event in current if event.get("id") not in sent]
        if keep:
            write_json_lines(path, keep)
        elif os.path.exists(path):
            os.remove(path)
    return len(batch) if outcome == "ok" else 0


def post_json(url, token, payload, timeout=5):
    req = urllib.request.Request(
        url,
        data=json.dumps(payload).encode(),
        headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as response:
            raw = response.read()
            return response.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as exc:
        return exc.code, {}
    except (urllib.error.URLError, OSError, ValueError):
        return 0, {}


def hermes_version():
    env = os.environ.get("HERMES_VERSION", "").strip()
    if env:
        return env[:200]
    try:
        out = subprocess.check_output(["hermes", "--version"], timeout=2, stderr=subprocess.STDOUT, text=True)
    except (OSError, subprocess.SubprocessError):
        return "unknown"
    line = (out or "").strip().splitlines()
    return (line[-1] if line else "unknown")[:200] or "unknown"


def synthetic_refusal(text):
    """OpenAI ChatCompletion-szerű objektum: a Hermes `normalize_response` a `.choices[0].message`-t olvassa."""
    message = SimpleNamespace(content=text, tool_calls=None, reasoning=None, reasoning_details=None, refusal=None)
    choice = SimpleNamespace(message=message, finish_reason="stop")
    return SimpleNamespace(id="excellence-guard-block", choices=[choice], usage=None, model="excellence")


class Guard:
    def __init__(self, home, client=None, now=time.time):
        self.home = home
        self.client = client or SnapshotClient(home, now=now)
        self.now = now
        self.sessions = set()
        self.noticed = set()
        self.decisions = {}
        self.interval = 60
        self._version = None

    def current(self, force=False):
        try:
            return self.client.refresh(force=force)
        except Exception:
            log.exception("snapshot")
            return policy.interpret_cache(self.client.read(), self.now(), policy.OFFLINE_TTL_SECONDS)

    def _audit_snapshot(self):
        interpreted = self.current()
        if interpreted.get("kind") == "snapshot":
            return interpreted["snapshot"]
        if interpreted.get("kind") == "bound":
            return policy.bound_snapshot()
        return {"capabilities": {"audit_depth": "metadata"}, "policyVersion": "revoked"}

    def note_session(self, session_id):
        if session_id:
            self.sessions.add(str(session_id)[:200])

    def pre_tool_call(self, tool_name=None, args=None, **kwargs):
        try:
            if not isinstance(args, dict):
                args = kwargs.get("tool_input") if isinstance(kwargs.get("tool_input"), dict) else {}
            # P4/NFR: visszavonás a következő hívásnál. Ha a Control Plane down, D4 cache marad.
            decision = policy.decide_interpreted(self.current(force=True), tool_name, args, os.path.join(self.home, "attachments"))
            call_id = kwargs.get("tool_call_id")
            if call_id:
                self.decisions[str(call_id)] = decision.action
            self.note_session(kwargs.get("session_id"))
            if decision.unclassified:
                self._report_unclassified(tool_name, kwargs.get("session_id"))
            body = policy.hook_body(decision)
            return None if decision.action == "allow" else body
        except Exception:
            log.exception("pre_tool_call")
            return {"action": "block", "message": f"A céges ellenőrzés hibázott, ezért ezt a műveletet nem engedem. {policy.ASK}"}

    def _report_unclassified(self, tool_name, session_id):
        """#872: az admin „Besorolatlan eszközök” listájához. Argumentum nincs benne, csak a név és a verzió."""
        try:
            if self._version is None:
                self._version = hermes_version()
            meta = {"tool": str(tool_name)[:128], "hermesVersion": self._version}
            enqueue(self.home, build_event({"capabilities": {"audit_depth": "metadata"}}, session_id, None, "tool_unclassified", None, meta))
            self._flush_soon()
        except Exception:
            log.exception("tool_unclassified")

    def post_tool_call(self, tool_name=None, args=None, result=None, **kwargs):
        try:
            call_id = str(kwargs.get("tool_call_id") or "")
            decision = self.decisions.pop(call_id, None)
            event = build_event(
                self._audit_snapshot(),
                kwargs.get("session_id"),
                kwargs.get("turn_id"),
                "tool_call",
                {"args": args, "result": result},
                {
                    "tool": tool_name,
                    "origin": policy.tool_origin(tool_name),
                    "status": kwargs.get("status"),
                    "decision": decision,
                },
            )
            enqueue(self.home, event)
            self._flush_soon()
        except Exception:
            log.exception("post_tool_call")

    def pre_llm_call(self, session_id=None, user_message=None, turn_id=None, **kwargs):
        try:
            self.note_session(session_id)
            event = build_event(self._audit_snapshot(), session_id, turn_id, "user_prompt", user_message, {})
            enqueue(self.home, event)
            self._flush_soon()
        except Exception:
            log.exception("pre_llm_call")
        return None

    def post_llm_call(self, session_id=None, assistant_response=None, turn_id=None, **kwargs):
        try:
            event = build_event(self._audit_snapshot(), session_id, turn_id, "final", assistant_response, {})
            enqueue(self.home, event)
            self._flush_soon()
        except Exception:
            log.exception("post_llm_call")

    def on_session_start(self, session_id=None, **kwargs):
        try:
            self._share_mcp_tokens()
            self.note_session(session_id)
            self.current(force=True)
            self.beat()
            if session_id and session_id not in self.noticed:
                self.noticed.add(session_id)
                sys.stderr.write(policy.NOTICE + "\n")
        except Exception:
            log.exception("on_session_start")

    def on_session_end(self, session_id=None, **kwargs):
        self.sessions.discard(session_id)

    def expected_gateway_url(self):
        return expected_gateway_url(self.home)

    def install_execution_gates(self):
        """K4: a modellhívás végrehajtásánál (HTTP + aux funnel) fail-closed."""
        install_llm_egress_gate(self.expected_gateway_url)
        patch_auxiliary_hooks(self.expected_gateway_url)

    def pre_auxiliary_call(self, provider=None, base_url=None, **kwargs):
        """Observer: a blokkolást a HTTP-kapu és a `run_with_aux_hooks` wrap végzi."""
        client = kwargs.get("client")
        url = str(base_url or getattr(client, "base_url", "") or "")
        if policy.is_excellence_route(provider, url, self.expected_gateway_url()):
            return None
        raise ForeignLlmRoute(url or provider)

    def llm_execution(self, request=None, next_call=None, provider=None, base_url=None, **kwargs):
        self._share_mcp_tokens()
        token_helper = None
        try:
            token_helper = load_exc_token()
            expected_url = token_helper.read_profile(self.home)[0] + "/api/model-gateway/v1" if token_helper else None
            allowed = policy.is_excellence_route(provider, base_url, expected_url)
        except Exception as exc:
            log.exception("llm_execution")
            # A middleware fail-open: kivételre a Hermes továbbhívna. Inkább szintetikus elutasítás.
            # Az exc-token saját, érthető hibája (pl. nincs hozzárendelt asszisztens) ne modellhibának látsszon (#858).
            fail = getattr(token_helper, "Fail", ())
            return synthetic_refusal(str(exc) if isinstance(exc, fail) else policy.PROVIDER_BLOCK)
        if not allowed:
            return synthetic_refusal(policy.PROVIDER_BLOCK)
        # A kapu 180s után Open, ha a session lastSeenAt-je a háttérszál (másik folyamat) miatt kimarad.
        # Minden modellhívás előtt újra bejelentjük ezt a sessiont, ne csak az elsőt.
        sid = str(kwargs.get("session_id") or "")[:200]
        if sid:
            try:
                self.note_session(sid)
                self.beat()
            except Exception:
                log.exception("llm_execution heartbeat")
        if isinstance(request, dict):
            headers = dict(request.get("extra_headers") or {})
            for key, field in (("X-Excellence-Session", "session_id"), ("X-Excellence-Turn", "turn_id")):
                if kwargs.get(field):
                    headers = {name: value for name, value in headers.items() if name.lower() != key.lower()}
                    headers[key] = str(kwargs[field])[:200]
            # A Hermes a bare key_cmd jegyet 15 percig cache-eli, a gateway-JWT 10 perc. Friss token a kérésre.
            token, refused = self._gateway_token()
            if refused is not None:
                return refused
            headers = {name: value for name, value in headers.items() if name.lower() != "authorization"}
            headers["Authorization"] = f"Bearer {token}"
            request = {**request, "extra_headers": headers}
            # A Hermes stream-újrapróbálása a next_call-on belül ugyanezt a header-dictet küldi újra
            # (elakadt stream után 5+ perccel is) → a hívás alatt frissen tartjuk, különben lejárt JWT, 401.
            stop = threading.Event()
            threading.Thread(target=self._keep_token_fresh, args=(headers, stop), name="excellence-guard-token", daemon=True).start()
            try:
                return next_call(request)
            finally:
                stop.set()
        # A provider hibája a Hermes újrapróbálási/tömörítési útjára tartozik.
        return next_call(request)

    def _keep_token_fresh(self, headers, stop):
        # Az exc-token cache-ből ad, csak `exp - 60 s` után kér újat; hibánál a régi marad (a 401 úgyis látszik).
        while not stop.wait(TOKEN_REFRESH_SECONDS):
            token, refused = self._gateway_token()
            if refused is None:
                headers["Authorization"] = f"Bearer {token}"

    def _share_mcp_tokens(self):
        mod = load_exc_token()
        share = getattr(mod, "share_all_mcp_tokens", None) or getattr(mod, "share_mcp_tokens", None)
        if share is None:
            return
        try:
            share(self.home)
        except Exception:
            log.exception("share_mcp_tokens")

    def _gateway_token(self):
        """Egyetlen token-kérés: (token, None) vagy (None, elutasítás). Sosem JWT nélküli továbbítás (#895).
        A key_cmd Fail-t ne Hermes modellhibának hagyjuk: a user a magyar szöveget lássa."""
        mod = load_exc_token()
        if mod is None:
            return None, synthetic_refusal(policy.PROVIDER_BLOCK)
        try:
            token = mod.get_token(self.home)
        except Exception as exc:
            log.warning("gateway token: %s", exc)
            fail = getattr(mod, "Fail", ())
            return None, synthetic_refusal(str(exc) if isinstance(exc, fail) else policy.PROVIDER_BLOCK)
        if not token:
            log.warning("gateway token: üres")
            return None, synthetic_refusal(policy.PROVIDER_BLOCK)
        return token, None

    def _origin_and_token(self):
        mod = load_exc_token()
        if mod is None:
            return None, None
        try:
            return mod.read_profile(self.home)[0], mod.get_token(self.home)
        except Exception:
            return None, None

    def _flush_soon(self):
        if os.environ.get("EXC_GUARD_OFFLINE") == "1":
            return
        try:
            self.flush_audit()
        except Exception:
            log.exception("audit flush")

    def flush_audit(self):
        origin, token = self._origin_and_token()
        if not origin or not token:
            return 0

        def post(events):
            status, _body = post_json(f"{origin}/api/ai-audit/events", token, {"events": events})
            if 200 <= status < 300:
                return "ok"
            if status in (400, 413):
                return "drop"
            return "retry"

        return flush_queue(self.home, post)

    def beat(self):
        if os.environ.get("EXC_GUARD_OFFLINE") == "1":
            return
        origin, token = self._origin_and_token()
        if not origin or not token:
            return
        interpreted = self.current()
        if interpreted.get("kind") == "snapshot":
            version = interpreted["snapshot"].get("policyVersion") or "unknown"
        elif interpreted.get("kind") == "revoked":
            version = "revoked"
        else:
            version = "offline-bound"
        if self._version is None:
            self._version = hermes_version()
        payload = {
            "configHash": config_hash(self.home),
            "managedDirHash": reported_managed_dir_hash(),
            "policyVersion": str(version)[:200],
            "guardVersion": policy.GUARD_VERSION,
            "hermesVersion": self._version,
            "sessions": sorted(self.sessions)[:50],
        }
        status, body = post_json(f"{origin}/api/client-policy/heartbeat", token, payload)
        if status == 200 and isinstance(body, dict):
            interval = body.get("intervalSeconds")
            if isinstance(interval, int) and interval > 0:
                self.interval = interval

    def spawn(self):
        if os.environ.get("EXC_GUARD_DISABLE_BACKGROUND") == "1":
            return
        threading.Thread(target=self._loop, name="excellence-guard", daemon=True).start()

    def _loop(self):
        while True:
            time.sleep(max(self.interval, 15))
            try:
                self.current(force=True)
                self.beat()
                self.flush_audit()
            except Exception:
                log.exception("periodic")

excellence-guard/excellence_paths.py:
"""A céges telepítés útvonalai (#755).

A `machine-floor.ts` `CLIENT_COMMANDS.windows` ugyanezt a `C:\\ProgramData\\Excellence`
gyökeret írja a kiadott padlóba. Az `exc-token` `-I` mellett fut, ezért fájlútvonalról
tölti be ezt a modult, nem a `sys.path`-ról.
"""
import os

WINDOWS_ROOT = r"C:\ProgramData\Excellence"


class ManagedDirRedirected(Exception):
    """Windowson a felhasználói HERMES_MANAGED_DIR felülírná a gépszintű padlót."""


def default_managed_dir():
    if os.name == "nt":
        return WINDOWS_ROOT + r"\hermes"
    return "/etc/hermes"


def token_helper_path():
    if os.name == "nt":
        return WINDOWS_ROOT + r"\bin\exc-token"
    return "/opt/excellence/bin/exc-token"


def plugin_dir():
    if os.name == "nt":
        return WINDOWS_ROOT + r"\hermes-plugins\excellence-guard"
    return "/opt/excellence/hermes-plugins/excellence-guard"


def default_home():
    """A Hermes alapértelmezett profilja: Windowson %LOCALAPPDATA%\\hermes, máshol ~/.hermes."""
    if os.name == "nt":
        return os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser(r"~\AppData\Local"), "hermes")
    return os.path.expanduser("~/.hermes")


def resolve_managed_dir(env_value, windows):
    """A Hermes által látott könyvtár. Windowson csak a céges hely érvényes.

    A felhasználói környezeti változó a gépszintűt felülírja, natív managed hely
    pedig nincs (U3). Az eltérő értéket nem követjük: a hook és a hash ugyanazt
    a könyvtárat nézi, az átirányítás fail-closed.
    """
    default = (WINDOWS_ROOT + r"\hermes") if windows else "/etc/hermes"
    if not env_value:
        return default
    if windows:
        if env_value.rstrip("\\/").lower() == default.rstrip("\\/").lower():
            return default
        raise ManagedDirRedirected(env_value)
    return env_value
